export default {"html":"<p data-line=\"0\" class=\"code-line\">Talk notes from this event:</p>\n<p data-line=\"2\" class=\"code-line\"><a href=\"https://nishinomiya.connpass.com/event/367811/\" rel=\"noopener noreferrer\" target=\"_blank\">https://nishinomiya.connpass.com/event/367811/</a><a href=\"https://nishinomiya.connpass.com/event/367811/\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://nishinomiya.connpass.com/event/367811/</a></p>\n<hr data-line=\"4\" class=\"code-line\">\n<h2 id=\"authentication%3A-authentication-%26-authorization-%26-session-management\" data-line=\"7\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#authentication%3A-authentication-%26-authorization-%26-session-management\" aria-hidden=\"true\"></a> Authentication: Authentication &amp; Authorization &amp; Session Management</h2>\n<ul data-line=\"9\" class=\"code-line\">\n<li data-line=\"9\" class=\"code-line\">Authentication: proving who a user is</li>\n<li data-line=\"10\" class=\"code-line\">Authorization: deciding what a given user can do or see</li>\n<li data-line=\"11\" class=\"code-line\">Session management: state based on authentication (logged-in status, etc.)</li>\n<li data-line=\"12\" class=\"code-line\">Why the distinction matters (separation of concerns, safer design, avoiding misuse, etc.)</li>\n</ul>\n<h2 id=\"authentication\" data-line=\"14\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#authentication\" aria-hidden=\"true\"></a> Authentication</h2>\n<h3 id=\"what-authentication-is\" data-line=\"16\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#what-authentication-is\" aria-hidden=\"true\"></a> What Authentication Is</h3>\n<ul data-line=\"18\" class=\"code-line\">\n<li data-line=\"18\" class=\"code-line\">The first authentication on HTTP/the web (arguably): \"Basic authentication\"\n<ul data-line=\"19\" class=\"code-line\">\n<li data-line=\"19\" class=\"code-line\">Apache default <code>.htpasswd</code>\n<ul data-line=\"20\" class=\"code-line\">\n<li data-line=\"20\" class=\"code-line\">Minimal auth as a permission <code>boolean</code></li>\n<li data-line=\"21\" class=\"code-line\">Base64 encoding / plaintext storage / no session management!</li>\n<li data-line=\"22\" class=\"code-line\">Still used today as \"security that is OK if it leaks\"</li>\n</ul>\n</li>\n</ul>\n</li>\n<li data-line=\"23\" class=\"code-line\">Authentication is often compared to \"does this key fit the lock?\"</li>\n<li data-line=\"24\" class=\"code-line\">Whether you may enter—not strictly unique identification</li>\n<li data-line=\"25\" class=\"code-line\">Lose the key, replace the key—that is the idea</li>\n</ul>\n<h3 id=\"stepping-up-to-user-authentication\" data-line=\"27\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#stepping-up-to-user-authentication\" aria-hidden=\"true\"></a> Stepping Up to User Authentication</h3>\n<ul data-line=\"29\" class=\"code-line\">\n<li data-line=\"29\" class=\"code-line\">\n<p data-line=\"29\" class=\"code-line\">Different key per person = user authentication</p>\n</li>\n<li data-line=\"30\" class=\"code-line\">\n<p data-line=\"30\" class=\"code-line\">Main approaches</p>\n<ul data-line=\"31\" class=\"code-line\">\n<li data-line=\"31\" class=\"code-line\">Higher implementer risk\n<ul data-line=\"32\" class=\"code-line\">\n<li data-line=\"32\" class=\"code-line\">Password authentication (dictionary = unique keyword + password)</li>\n</ul>\n</li>\n<li data-line=\"33\" class=\"code-line\">Lower implementer risk\n<ul data-line=\"34\" class=\"code-line\">\n<li data-line=\"34\" class=\"code-line\">UUID authentication common in mobile apps</li>\n<li data-line=\"35\" class=\"code-line\">Multi-factor authentication (MFA, 2FA)</li>\n<li data-line=\"36\" class=\"code-line\">OAuth / OpenID Connect</li>\n<li data-line=\"37\" class=\"code-line\">Passwordless authentication</li>\n</ul>\n</li>\n</ul>\n</li>\n<li data-line=\"38\" class=\"code-line\">\n<p data-line=\"38\" class=\"code-line\">Typical password authentication</p>\n<ul data-line=\"39\" class=\"code-line\">\n<li data-line=\"39\" class=\"code-line\">Email address + password pair</li>\n<li data-line=\"40\" class=\"code-line\">Why email address?\n<ul data-line=\"41\" class=\"code-line\">\n<li data-line=\"41\" class=\"code-line\">Verifies ownership and is unique</li>\n<li data-line=\"42\" class=\"code-line\">Send reset URL when password is forgotten</li>\n<li data-line=\"43\" class=\"code-line\">No separate marketing email question</li>\n<li data-line=\"44\" class=\"code-line\">Users forget less (you hope)</li>\n<li data-line=\"45\" class=\"code-line\">Fundamentally any unique username works</li>\n</ul>\n</li>\n<li data-line=\"46\" class=\"code-line\">Why password?\n<ul data-line=\"47\" class=\"code-line\">\n<li data-line=\"47\" class=\"code-line\">Only the user should know it (you hope)</li>\n<li data-line=\"48\" class=\"code-line\">No special device—low account creation cost</li>\n</ul>\n</li>\n</ul>\n</li>\n<li data-line=\"49\" class=\"code-line\">\n<p data-line=\"49\" class=\"code-line\">Implementer risk</p>\n<ul data-line=\"50\" class=\"code-line\">\n<li data-line=\"50\" class=\"code-line\">You hold the key pair—always breach risk\n<ul data-line=\"51\" class=\"code-line\">\n<li data-line=\"51\" class=\"code-line\"><a href=\"https://rocket-boys.co.jp/security-measures-lab/unauthorized-access-to-so-net-accounts-some-user-email-addresses-accidentally-changed/\" target=\"_blank\" rel=\"noopener noreferrer\">https://rocket-boys.co.jp/security-measures-lab/unauthorized-access-to-so-net-accounts-some-user-email-addresses-accidentally-changed/</a></li>\n<li data-line=\"52\" class=\"code-line\"><a href=\"https://www.itmedia.co.jp/news/articles/2410/23/news133.html\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.itmedia.co.jp/news/articles/2410/23/news133.html</a></li>\n</ul>\n</li>\n<li data-line=\"53\" class=\"code-line\">\"Manners\" to reduce risk\n<ul data-line=\"54\" class=\"code-line\">\n<li data-line=\"54\" class=\"code-line\">Admins should not know what they should not know\n<ul data-line=\"55\" class=\"code-line\">\n<li data-line=\"55\" class=\"code-line\">\"Show password\" seems convenient for support</li>\n<li data-line=\"56\" class=\"code-line\">You should not know passwords—build password reset\n<ul data-line=\"57\" class=\"code-line\">\n<li data-line=\"57\" class=\"code-line\">To match user ID and password</li>\n<li data-line=\"58\" class=\"code-line\">Hash (one-way, unlike encryption) for comparison</li>\n<li data-line=\"59\" class=\"code-line\">Store user ID plaintext for uniqueness; hash password only</li>\n<li data-line=\"60\" class=\"code-line\">User ID needed to distinguish users with the same password</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul>\n</li>\n<li data-line=\"61\" class=\"code-line\">Email + password pairs are reused—leaks may work on other sites</li>\n<li data-line=\"62\" class=\"code-line\">Is hashing enough?\n<ul data-line=\"63\" class=\"code-line\">\n<li data-line=\"63\" class=\"code-line\">Focus on the password <em>before</em> processing</li>\n<li data-line=\"64\" class=\"code-line\">Password complexity</li>\n<li data-line=\"65\" class=\"code-line\">Brute-force and dictionary attack mitigation</li>\n<li data-line=\"66\" class=\"code-line\">Password reset can be a security risk depending on implementation…</li>\n</ul>\n</li>\n</ul>\n</li>\n<li data-line=\"68\" class=\"code-line\">\n<p data-line=\"68\" class=\"code-line\">Since we touched implementation, authorization &amp; session management too</p>\n</li>\n<li data-line=\"69\" class=\"code-line\">\n<p data-line=\"69\" class=\"code-line\">Authorization</p>\n<ul data-line=\"70\" class=\"code-line\">\n<li data-line=\"70\" class=\"code-line\">Authentication: key fits the lock / Authorization: which rooms you may enter</li>\n<li data-line=\"71\" class=\"code-line\">Representative authorization models\n<ul data-line=\"72\" class=\"code-line\">\n<li data-line=\"72\" class=\"code-line\">Role-based: roles (AWS IAM is easy to picture)</li>\n<li data-line=\"73\" class=\"code-line\">Attribute-based: department, location, payment status, etc.</li>\n<li data-line=\"74\" class=\"code-line\">Access control lists: per resource—honestly unmaintainable</li>\n</ul>\n</li>\n</ul>\n</li>\n<li data-line=\"75\" class=\"code-line\">\n<p data-line=\"75\" class=\"code-line\">Sessions</p>\n<ul data-line=\"76\" class=\"code-line\">\n<li data-line=\"76\" class=\"code-line\">Requiring the key every request means users must store the key too</li>\n<li data-line=\"77\" class=\"code-line\">Before encryption—absurd</li>\n<li data-line=\"78\" class=\"code-line\">Like an entry pass instead of the key</li>\n<li data-line=\"79\" class=\"code-line\">Server-side session or token-based (stateless)</li>\n</ul>\n</li>\n<li data-line=\"81\" class=\"code-line\">\n<p data-line=\"81\" class=\"code-line\">Are lower-risk approaches always better?</p>\n<ul data-line=\"82\" class=\"code-line\">\n<li data-line=\"82\" class=\"code-line\">UUID authentication common in mobile apps</li>\n<li data-line=\"83\" class=\"code-line\">Multi-factor authentication (MFA, 2FA)</li>\n<li data-line=\"84\" class=\"code-line\">OAuth / OpenID Connect</li>\n<li data-line=\"85\" class=\"code-line\">Passwordless authentication</li>\n</ul>\n</li>\n<li data-line=\"87\" class=\"code-line\">\n<p data-line=\"87\" class=\"code-line\">Use external services for authentication</p>\n<ul data-line=\"88\" class=\"code-line\">\n<li data-line=\"88\" class=\"code-line\">Firebase Authentication</li>\n<li data-line=\"89\" class=\"code-line\">Auth0</li>\n</ul>\n</li>\n<li data-line=\"91\" class=\"code-line\">\n<p data-line=\"91\" class=\"code-line\">Privacy policy and disclosure requests</p>\n<ul data-line=\"92\" class=\"code-line\">\n<li data-line=\"92\" class=\"code-line\">Telecom carrier disclosure obligations</li>\n<li data-line=\"93\" class=\"code-line\">Provider liability limitation law (Japan)</li>\n<li data-line=\"94\" class=\"code-line\">Rolling your own auth often costs more in risk than engineering</li>\n<li data-line=\"95\" class=\"code-line\">Draw the line on where your responsibility ends</li>\n</ul>\n</li>\n</ul>\n","headings":[{"id":"authentication%3A-authentication-%26-authorization-%26-session-management","text":"Authentication: Authentication & Authorization & Session Management","level":2},{"id":"authentication","text":"Authentication","level":2},{"id":"what-authentication-is","text":"What Authentication Is","level":3},{"id":"stepping-up-to-user-authentication","text":"Stepping Up to User Authentication","level":3}]} as const;
